function w({registerIndicator:d,nulls:g}){d({id:"oa-asi",name:"Accumulation Swing Index (ASI)",category:"Momentum",placement:"pane",inputs:[{key:"limitMove",type:"number",label:"Limit Move",default:3,min:.001,max:1e6,step:.1,tooltip:"Maximum daily price change (T). Use 3.0 for stocks, adjust for futures or forex."}],plots:[{key:"asi",type:"line",title:"ASI",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86",dashed:!0}],calc(t,y){const M=t.length,v=Math.max(.001,Number(y.limitMove)||3),r=new Array(M).fill(NaN);let m=0;for(let e=0;e<M;e++){const l=t[e],u=l.high,p=l.low,a=l.close,b=l.open;if(!Number.isFinite(u)||!Number.isFinite(p)||!Number.isFinite(a)||!Number.isFinite(b)){r[e]=m;continue}const n=e>0&&Number.isFinite(t[e-1].close)?t[e-1].close:a,N=e>0&&Number.isFinite(t[e-1].open)?t[e-1].open:b;let c=0;if(e>0){const i=Math.abs(u-n),o=Math.abs(p-n),f=Math.abs(u-p),h=Math.abs(n-N),x=Math.max(i,o);let s;i>=o&&i>=f?s=i-.5*o+.25*h:o>=i&&o>=f?s=o-.5*i+.25*h:s=f+.25*h,s!==0&&(c=50*(a-n+.5*(a-b)+.25*(n-N))/s*(x/v))}Number.isFinite(c)||(c=0),m+=c,r[e]=m}return{asi:g(r)}}})}export{w as default};
